-- MIGRATION SUPABASE — PrixCI v4
-- À exécuter dans : Supabase Dashboard > SQL Editor
-- Prérequis : supabase_migration_v3.sql
-- Idempotent : peut être relancé sans risque. Ne supprime aucune donnée.
--
-- Contenu :
--   1. Prix mini et maxi dans la table des prix officiels
--   2. Relevé hebdomadaire OCPV du 7 au 13 septembre 2026 (24 régions)
-- ============================================================

ALTER TABLE public.prix_reference
  ADD COLUMN IF NOT EXISTS prix_min NUMERIC(10, 0),
  ADD COLUMN IF NOT EXISTS prix_max NUMERIC(10, 0);

-- Relevé OCPV : prix moyen, mini et maxi relevés sur les marchés, en F CFA/kg.
-- Retranscrit depuis le PDF officiel ; 4 cases manifestement erronées écartées.
ON CONFLICT (type, produit_id, unite, ville, date_debut) DO NOTHING;

-- Vérification :
